const root=document.getElementById('app');
const routes={dashboard:['لوحة التحكم','▦',['manager','finance','sales','inventory','production']],users:['المستخدمون','♙',['manager']],roles:['الأدوار والصلاحيات','◆',['manager']],employees:['الموظفون والوظائف','♙',['manager','finance']],attendance:['الحضور والورديات','◷',['manager','finance']],products:['المنتجات','◇',['manager','inventory','sales','production']],inventory:['المخزن والوارد والصادر','▤',['manager','inventory','sales','production']],production:['الإنتاج','⚙',['manager','production']],sales:['المبيعات والعملاء','▣',['manager','sales']],expenses:['المصروفات','−',['manager','finance']],treasury:['الخزنة والبنوك','▥',['manager','finance']],payroll:['المرتبات والسلفيات','₿',['manager','finance']],reports:['التقارير والطباعة','▤',['manager','finance']],audit:['سجل التدقيق','⌁',['manager']],settings:['إعدادات المصنع','⚙',['manager']],guide:['دليل التشغيل','?',['manager','finance','sales','inventory','production']]};
const groups=[['الرئيسية',['dashboard','guide']],['الإدارة',['users','roles','employees','attendance']],['التشغيل',['products','inventory','production','sales']],['المالية',['expenses','treasury','payroll']],['المتابعة',['reports','audit','settings']]];
const roleNames={manager:'المدير',finance:'الحسابات',sales:'المبيعات',inventory:'المخزن',production:'الإنتاج'};
const statusNames={draft:'مسودة',pending:'بانتظار الاعتماد',approved:'معتمد',cancelled:'ملغى',paid:'مدفوع',partially_paid:'مدفوع جزئيًا',active:'نشط',suspended:'موقوف',on_leave:'في إجازة',left_work:'ترك العمل',archived:'مؤرشف',present:'حاضر',late:'متأخر',absent:'غائب',leave:'إجازة',missing_checkout:'لم يسجل الانصراف'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const money=v=>`${new Intl.NumberFormat('ar-SD',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${appConfig.currency||'ج.س'}`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:appConfig.timezone||'Africa/Khartoum'}).format(new Date());
const dateText=v=>v?new Intl.DateTimeFormat('ar-SD',{dateStyle:'medium',timeZone:appConfig.timezone||'Africa/Khartoum'}).format(new Date(v)):'—';
const label=v=>statusNames[v]||v||'—';
function approveBtn(fn,id){return role()==='manager'?`<button class="btn btn-soft" data-action="approve" data-approve="${fn}" data-id="${id}">اعتماد</button>`:''}
function role(){return profile?.role||'manager'} function can(r){return routes[r]?.[2]?.includes(role())}
function options(rows,key='name',placeholder='اختر'){return `<option value="">${placeholder}</option>${rows.map(x=>`<option value="${esc(x.id||x.code)}"${x.sale_price!==undefined?` data-sale-price="${esc(x.sale_price)}" data-purchase-price="${esc(x.purchase_price||0)}" data-unit="${esc(x.unit_code||'piece')}"`:''}>${esc(x[key]||x.name_ar||x.full_name||x.code)}</option>`).join('')}`}
function btn(text,action='',kind='primary'){return `<button class="btn btn-${kind}" data-action="${action}">${esc(text)}</button>`}
function head(title,sub,actions=''){return `<div class="page-header"><div><div class="eyebrow">مصنع الصندل · ${esc(roleNames[role()]||'المدير')}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="header-actions">${actions}</div></div>`}
function empty(title,sub='لا توجد بيانات مسجلة حتى الآن.'){return `<div class="empty-state"><b>${esc(title)}</b><span>${esc(sub)}</span></div>`}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('لا توجد بيانات','ابدأ بإضافة أول سجل من الزر أعلاه.')}
function shell(content,route){return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="sidebar-brand"><span class="brand-symbol">SP</span><div><strong>مصنع الصندل</strong><small>إدارة المصنع الذكية</small></div></div>${groups.map(([name,items])=>{const visible=items.filter(can);return visible.length?`<div class="nav-group"><div class="nav-label">${name}</div><nav class="nav-list">${visible.map(r=>`<a class="nav-item ${r===route?'active':''}" href="#/${r}"><span class="nav-icon">${routes[r][1]}</span>${routes[r][0]}</a>`).join('')}</nav></div>`:''}).join('')}<div class="sidebar-bottom"><div class="connection"><i class="dot"></i> النظام متصل وآمن</div></div></aside><section class="main-area"><header class="topbar"><div class="topbar-left"><button class="menu-btn" data-action="menu">☰</button><div><div class="topbar-title">${esc(routes[route]?.[0]||'لوحة التحكم')}</div><div class="topbar-date">${esc(new Intl.DateTimeFormat('ar-SD',{dateStyle:'full',timeZone:appConfig.timezone||'Africa/Khartoum'}).format(new Date()))}</div></div></div><div class="profile-box"><div><strong>${esc(profile?.full_name||profile?.email||'المستخدم')}</strong><small>${esc(profile?.roleName||roleNames[role()]||'المدير')}</small></div><span class="avatar">${esc((profile?.full_name||'م').slice(0,1))}</span><button class="btn btn-outline" data-action="logout">خروج</button></div></header><main class="content">${content}</main></section></div>`}
function login(){return `<div class="login-page"><section class="login-art"><div class="login-brand"><span class="brand-symbol">SP</span><div><strong>مصنع الصندل</strong><small>للأوعية البلاستيكية</small></div></div><div><h1>كل عمليات المصنع، في مكان واحد.</h1><p>إدارة المبيعات والمخزن والإنتاج والموظفين والمالية بوضوح، من أول يوم تشغيل.</p></div><div class="login-note">نظام داخلي لإدارة مصنع الصندل للأوعية البلاستيكية</div></section><section class="login-form-side"><div class="login-card"><div class="eyebrow">بوابة الإدارة</div><h2>تسجيل الدخول</h2><p class="sub">أدخل بياناتك للوصول إلى الأقسام المصرح بها.</p><form id="login-form"><label class="field">البريد الإلكتروني<input name="email" type="email" autocomplete="username" required placeholder="name@factory.com"></label><label class="field">كلمة المرور<input name="password" type="password" autocomplete="current-password" required placeholder="••••••••"></label><button class="btn btn-primary btn-wide" type="submit">دخول إلى النظام</button><div id="login-error" class="error"></div></form></div></section></div>`}
async function dashboard(){let d={};try{d=await dbRpc('manager_dashboard_summary')||{}}catch(e){}const gross=Number(d.today_sales||0)-Number(d.today_cost||0),net=gross-Number(d.today_expenses||0);return `${head('لوحة التحكم','صورة يومية سريعة عن أداء المصنع',btn('تحديث','reload','outline'))}<section class="stats-grid"><div class="stat-card"><div class="stat-top">مبيعات اليوم <span class="stat-icon">▣</span></div><div class="stat-value">${money(d.today_sales)}</div><div class="stat-foot">من الفواتير المعتمدة</div></div><div class="stat-card"><div class="stat-top">الربح قبل المصروفات <span class="stat-icon">↗</span></div><div class="stat-value">${money(gross)}</div><div class="stat-foot">المبيعات ناقص التكلفة</div></div><div class="stat-card"><div class="stat-top">رصيد الخزنة <span class="stat-icon">▥</span></div><div class="stat-value">${money(d.cash_balance)}</div><div class="stat-foot">الرصيد الحالي</div></div><div class="stat-card"><div class="stat-top">الحضور اليوم <span class="stat-icon">◷</span></div><div class="stat-value">${Number(d.present_today||0)} <small style="font-size:12px;color:var(--muted)">من ${Number(d.total_employees||0)}</small></div><div class="stat-foot">حاضر ومتأخر</div></div></section><section class="dashboard-grid"><div class="panel profit-card"><div class="panel-head"><div><h2 class="panel-title">ملخص صافي اليوم</h2><p class="panel-sub">حساب آلي من العمليات المعتمدة فقط</p></div><span class="badge">${today()}</span></div><div class="profit-number">${money(net)}</div><div class="profit-caption">الصافي بعد المصروفات</div><div class="progress"><i style="width:${gross>0?Math.min(100,Math.max(5,net/gross*100)):5}%"></i></div><div class="split"><div><small>المصروفات</small><strong>${money(d.today_expenses)}</strong></div><div><small>الإنتاج المقبول</small><strong>${Number(d.today_production||0)}</strong></div></div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">إجراءات سريعة</h2><p class="panel-sub">أكثر العمليات استخدامًا</p></div></div><div class="quick-actions"><a class="quick-action" href="#/sales"><i>▣</i><div><strong>تسجيل مبيع</strong><small>فاتورة جديدة</small></div></a><a class="quick-action" href="#/inventory"><i>▤</i><div><strong>وارد / صادر</strong><small>حركة مخزن</small></div></a><a class="quick-action" href="#/expenses"><i>−</i><div><strong>تسجيل منصرف</strong><small>مصروف جديد</small></div></a><a class="quick-action" href="#/attendance"><i>◷</i><div><strong>تسجيل حضور</strong><small>حضور العاملين</small></div></a></div></div></section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">ملخص التشغيل</h2><p class="panel-sub">تنبيهات تحتاج متابعة</p></div><a class="btn btn-soft" href="#/reports">كل التقارير</a></div><div class="metric-line"><span>طلبات بانتظار الاعتماد</span><strong>${Number(d.pending_count||0)}</strong></div><div class="metric-line"><span>موظفون لم يسجلوا الانصراف</span><strong>${Number(d.missing_checkout||0)}</strong></div><div class="metric-line"><span>أصناف تحت الحد الأدنى</span><strong>${Number(d.low_stock_count||0)}</strong></div></section>`}
async function users(){const [ps,urs,rs]=await Promise.all([dbSelect('profiles','id,email,full_name,is_enabled,created_at',{order:{column:'created_at',ascending:false},limit:100}),dbSelect('user_roles','user_id,role_id',{limit:200}),dbSelect('roles','id,code,name_ar',{order:{column:'code'}})]);const roleMap=Object.fromEntries(rs.map(r=>[r.id,{name:r.name_ar,code:r.code}]));const assigned=Object.fromEntries(urs.map(r=>[r.user_id,roleMap[r.role_id]||{name:'بدون دور',code:'sales'}]));return `${head('المستخدمون','من يدخل النظام وما القسم المسموح له به',btn('إضافة مستخدم','user-modal'))}<section class="panel table-panel">${table(['المستخدم','البريد الإلكتروني','الدور','الحالة','تاريخ الإنشاء','الإجراء'],ps.map(p=>`<tr><td><strong>${esc(p.full_name||'بدون اسم')}</strong></td><td>${esc(p.email)}</td><td><span class="badge blue">${esc(assigned[p.id].name)}</span></td><td><span class="badge">${p.is_enabled?'نشط':'موقوف'}</span></td><td>${dateText(p.created_at)}</td><td><button class="btn btn-soft" data-action="edit-user" data-id="${p.id}" data-name="${esc(p.full_name||'')}" data-email="${esc(p.email||'')}" data-role="${esc(assigned[p.id].code)}" data-enabled="${p.is_enabled}">تعديل</button></td></tr>`))}</section>`}
async function roles(){const [rs,ps,rps]=await Promise.all([dbSelect('roles','id,code,name_ar,description',{order:{column:'code'}}),dbSelect('permissions','id,code,name_ar,module',{order:{column:'module'},limit:200}),dbSelect('role_permissions','role_id,permission_id',{limit:500})]);const counts=Object.fromEntries(rs.map(r=>[r.id,rps.filter(x=>x.role_id===r.id).length]));return `${head('الأدوار والصلاحيات','حدد ماذا يستطيع كل مستخدم أن يرى أو ينفذ',btn('حفظ الصلاحيات','noop','soft'))}<section class="section-grid">${rs.map(r=>`<div class="section-card"><div class="section-icon">◆</div><h3>${esc(r.name_ar)}</h3><p>${esc(r.description||'صلاحيات مرنة حسب دور المستخدم')}</p><div class="metric-line"><span>الصلاحيات الممنوحة</span><strong>${counts[r.id]||0} من ${ps.length}</strong></div></div>`).join('')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">مصفوفة الصلاحيات</h2><p class="panel-sub">كل صلاحية مصنفة حسب القسم</p></div></div>${table(['القسم','الصلاحية','الكود الداخلي'],ps.map(p=>`<tr><td>${esc(p.module)}</td><td>${esc(p.name_ar)}</td><td><span class="badge">${esc(p.code)}</span></td></tr>`))}</section>`}
async function employees(){const [rows,depts,titles,shifts]=await Promise.all([dbSelect('employees','id,employee_number,full_name,phone,employment_date,wage_type,base_salary,status,department_id,job_title_id,default_shift_id',{order:{column:'created_at',ascending:false},limit:200}),dbSelect('departments','id,name',{order:{column:'name'}}),dbSelect('job_titles','id,name',{order:{column:'name'}}),dbSelect('shifts','id,name',{order:{column:'name'}})]);const deptNames=Object.fromEntries(depts.map(x=>[x.id,x.name])),titleNames=Object.fromEntries(titles.map(x=>[x.id,x.name])),shiftNames=Object.fromEntries(shifts.map(x=>[x.id,x.name]));return `${head('الموظفون والوظائف','سجل كل عامل باسمه ووظيفته وقسمه وورديته',btn('موظف جديد','employee-modal'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">قائمة العاملين</h2><p class="panel-sub">الرقم الوظيفي يتولد تلقائيًا بصيغة SD-EMP-0001</p></div><input class="search" data-search="employee-table" placeholder="ابحث باسم العامل أو الرقم"></div>${table(['الرقم','اسم العامل','القسم','الوظيفة','الوردية','الهاتف','الأجر','الحالة'],rows.map(r=>`<tr><td><span class="badge blue">${esc(r.employee_number)}</span></td><td><strong>${esc(r.full_name)}</strong></td><td>${esc(deptNames[r.department_id]||'—')}</td><td>${esc(titleNames[r.job_title_id]||'—')}</td><td>${esc(shiftNames[r.default_shift_id]||'—')}</td><td>${esc(r.phone||'—')}</td><td>${money(r.base_salary)}</td><td><span class="badge">${label(r.status)}</span></td></tr>`))}</section>`}
async function attendance(){const [es,rows,shifts]=await Promise.all([dbSelect('employees','id,employee_number,full_name,department_id,default_shift_id',{eq:{status:'active'},order:{column:'full_name'}}),dbSelect('attendance_records','id,employee_id,status,check_in_at,check_out_at,working_minutes',{order:{column:'check_in_at',ascending:false},limit:300}),dbSelect('shifts','id,name',{order:{column:'name'}})]);const localDay=today();const todayRows=rows.filter(r=>r.check_in_at&&new Intl.DateTimeFormat('en-CA',{timeZone:appConfig.timezone||'Africa/Khartoum'}).format(new Date(r.check_in_at))===localDay);const latest=Object.fromEntries(todayRows.map(r=>[r.employee_id,r]));const cards=es.map(e=>{const a=latest[e.id];const open=a&&!a.check_out_at;return `<div class="section-card"><div class="section-icon">${open?'◷':'♙'}</div><h3>${esc(e.full_name)}</h3><p>${esc(e.employee_number)} · ${esc(shifts.find(s=>s.id===e.default_shift_id)?.name||'بدون وردية')}</p><div class="metric-line"><span>${open?'وقت الحضور':'الحالة'}</span><strong>${open?dateText(a.check_in_at):'لم يسجل اليوم'}</strong></div><button class="btn ${open?'btn-danger':'btn-primary'}" data-action="attendance-toggle" data-employee="${e.id}" data-attendance-action="${open?'check_out':'check_in'}">${open?'تسجيل الانصراف':'تسجيل الحضور'}</button></div>`}).join('');return `${head('الحضور والورديات','اضغط زر الموظف؛ النظام يسجل الوقت ويحسب الساعات تلقائيًا',btn('تصحيح سجل','attendance-modal','outline'))}<section class="section-grid">${cards||empty('لا يوجد موظفون نشطون','أضف الموظفين أولًا من صفحة الموظفين والوظائف.')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">سجل اليوم</h2><p class="panel-sub">المدة تحسب تلقائيًا من وقت الحضور إلى وقت الانصراف</p></div></div>${table(['العامل','الحالة','الحضور','الانصراف','ساعات العمل'],todayRows.map(r=>`<tr><td><strong>${esc(es.find(e=>e.id===r.employee_id)?.full_name||'—')}</strong></td><td><span class="badge ${r.status==='absent'?'danger':''}">${label(r.status)}</span></td><td>${dateText(r.check_in_at)}</td><td>${r.check_out_at?dateText(r.check_out_at):'<span class="badge warn">مفتوح</span>'}</td><td>${r.working_minutes!=null?`${Math.floor(r.working_minutes/60)} س ${r.working_minutes%60} د`:'—'}</td></tr>`))}</section>`}
async function products(){const [rows,cats]=await Promise.all([dbSelect('products','id,name,code,product_type,unit_code,purchase_price,sale_price,minimum_stock,is_active',{order:{column:'name'},limit:200}),dbSelect('product_categories','id,name',{order:{column:'name'}})]);return `${head('المنتجات','أكياس، حبال، مخلاية وحاويات، سلفان، والمواد الخام',btn('منتج جديد','product-modal'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">دليل المنتجات</h2><p class="panel-sub">الأسعار والوحدة والحد الأدنى للمخزون</p></div><input class="search" data-search="product-table" placeholder="ابحث عن منتج"></div>${table(['المنتج','الكود','النوع','الوحدة','سعر الشراء','سعر البيع','الحد الأدنى'],rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.code||'—')}</td><td>${r.product_type==='finished_product'?'منتج نهائي':'مادة خام'}</td><td>${esc(r.unit_code)}</td><td>${money(r.purchase_price)}</td><td>${money(r.sale_price)}</td><td>${r.minimum_stock}</td></tr>`))}</section>`}
async function inventory(){const [ms,rows,products,warehouses]=await Promise.all([dbSelect('stock_movements','id,document_number,direction,movement_type,movement_date,status,warehouse_id',{order:{column:'movement_date',ascending:false},limit:100}),dbSelect('v_stock_balances','product_id,product_name,warehouse_name,balance,minimum_stock',{order:{column:'product_name'},limit:300}),dbSelect('products','id,name',{order:{column:'name'}}),dbSelect('warehouses','id,name',{order:{column:'name'}})]);return `${head('المخزن والوارد والصادر','الرصيد يتغير من الحركات المعتمدة فقط، بلا تعديل يدوي',btn('حركة وارد / صادر','stock-modal'))}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">الأرصدة الحالية</h2><p class="panel-sub">تنبيه تلقائي عند النزول تحت الحد الأدنى</p></div></div>${table(['الصنف','المخزن','الرصيد','الحد الأدنى','الحالة'],rows.map(r=>`<tr><td><strong>${esc(r.product_name)}</strong></td><td>${esc(r.warehouse_name)}</td><td>${r.balance}</td><td>${r.minimum_stock}</td><td><span class="badge ${Number(r.balance)<Number(r.minimum_stock)?'warn':''}">${Number(r.balance)<Number(r.minimum_stock)?'تحت الحد':'جيد'}</span></td></tr>`))}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">آخر الحركات</h2></div></div>${table(['المستند','الاتجاه','السبب','الحالة','التاريخ','الإجراء'],ms.map(r=>`<tr><td>${esc(r.document_number)}</td><td><span class="badge ${r.direction==='out'?'warn':''}">${r.direction==='in'?'وارد':'صادر'}</span></td><td>${esc(r.movement_type)}</td><td>${label(r.status)}</td><td>${dateText(r.movement_date)}</td><td>${r.status==='draft'?approveBtn('approve_stock_movement',r.id):'—'}</td></tr>`))}</section>`}
async function production(){const [rows,products,shifts,emps]=await Promise.all([dbSelect('production_orders','id,order_number,production_date,planned_quantity,actual_quantity,damaged_quantity,accepted_quantity,status',{order:{column:'production_date',ascending:false},limit:100}),dbSelect('products','id,name',{eq:{product_type:'finished_product'},order:{column:'name'}}),dbSelect('shifts','id,name',{order:{column:'name'}}),dbSelect('employees','id,full_name',{order:{column:'full_name'}})]);return `${head('الإنتاج','تابع الإنتاج المخطط والمقبول والتالف لكل وردية',btn('أمر إنتاج جديد','production-modal'))}<section class="panel table-panel">${table(['الأمر','التاريخ','المنتج','المخطط','المقبول','التالف','الحالة','الإجراء'],rows.map(r=>`<tr><td>${esc(r.order_number)}</td><td>${esc(r.production_date)}</td><td>—</td><td>${r.planned_quantity}</td><td>${r.accepted_quantity}</td><td>${r.damaged_quantity}</td><td><span class="badge">${label(r.status)}</span></td><td>${r.status==='draft'?approveBtn('approve_production_order',r.id):'—'}</td></tr>`))}</section>`}
async function sales(){const [rows,products,warehouses,regs,banks]=await Promise.all([dbSelect('sales','id,invoice_number,total,payment_method,status,sold_at',{order:{column:'sold_at',ascending:false},limit:100}),dbSelect('products','id,name,sale_price,purchase_price,unit_code',{eq:{product_type:'finished_product'},order:{column:'name'}}),dbSelect('warehouses','id,name',{order:{column:'name'}}),dbSelect('cash_registers','id,name',{order:{column:'name'}}),dbSelect('banks','id,name',{order:{column:'name'}})]);return `${head('المبيعات والعملاء','الفاتورة، الدفع، المخزن، وحساب الربح من عملية واحدة',btn('فاتورة بيع جديدة','sale-modal'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">الفواتير</h2><p class="panel-sub">لا تؤثر الفاتورة على المخزن أو الخزنة إلا بعد الاعتماد</p></div><input class="search" data-search="sales-table" placeholder="ابحث برقم الفاتورة"></div>${table(['الفاتورة','المبلغ','طريقة الدفع','الحالة','التاريخ','الإجراء'],rows.map(r=>`<tr><td><strong>${esc(r.invoice_number)}</strong></td><td>${money(r.total)}</td><td>${r.payment_method==='cash'?'نقدي':'بنكي'}</td><td><span class="badge ${r.status==='approved'?'blue':''}">${label(r.status)}</span></td><td>${dateText(r.sold_at)}</td><td>${r.status==='draft'?approveBtn('approve_sale',r.id):'—'}</td></tr>`))}</section>`}
async function expenses(){const [rows,cats,regs,banks]=await Promise.all([dbSelect('expenses','id,expense_number,amount,payment_method,expense_date,status,description',{order:{column:'expense_date',ascending:false},limit:100}),dbSelect('expense_categories','id,name',{order:{column:'name'}}),dbSelect('cash_registers','id,name',{order:{column:'name'}}),dbSelect('banks','id,name',{order:{column:'name'}})]);return `${head('المصروفات','سجّل صُرف في شنو، ومن أي خزنة أو بنك',btn('منصرف جديد','expense-modal'))}<section class="panel table-panel">${table(['المستند','البيان','المبلغ','طريقة الدفع','الحالة','التاريخ','الإجراء'],rows.map(r=>`<tr><td>${esc(r.expense_number)}</td><td><strong>${esc(r.description||'—')}</strong></td><td>${money(r.amount)}</td><td>${r.payment_method==='cash'?'نقدي':'بنكي'}</td><td><span class="badge">${label(r.status)}</span></td><td>${dateText(r.expense_date)}</td><td>${r.status==='draft'?approveBtn('approve_expense',r.id):'—'}</td></tr>`))}</section>`}
async function treasury(){const [regs,banks,cts,bts]=await Promise.all([dbSelect('cash_registers','id,name,opening_balance,is_active',{order:{column:'name'}}),dbSelect('banks','id,name,account_number_masked,is_active',{order:{column:'name'}}),dbSelect('cash_transactions','id,transaction_number,direction,transaction_type,amount,transaction_at',{order:{column:'transaction_at',ascending:false},limit:50}),dbSelect('bank_transactions','id,transaction_number,direction,transaction_type,amount,transaction_at',{order:{column:'transaction_at',ascending:false},limit:50})]);return `${head('الخزنة والبنوك','كل حركة مالية مرتبطة بمستند واضح ولا يوجد تعديل مباشر للرصيد',btn('حركة خزنة','cash-modal'))}<section class="section-grid">${regs.map(r=>`<div class="section-card"><div class="section-icon">▥</div><h3>${esc(r.name)}</h3><p>الرصيد الافتتاحي: ${money(r.opening_balance)}</p><div class="metric-line"><span>الحالة</span><strong>${r.is_active?'نشطة':'موقوفة'}</strong></div></div>`).join('')||empty('لا توجد خزن','أضف خزنة من الإعدادات.')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">البنوك</h2></div></div>${table(['البنك','رقم الحساب','الحالة'],banks.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.account_number_masked||'—')}</td><td>${b.is_active?'نشط':'موقوف'}</td></tr>`))}</section>`}
async function payroll(){const [adv,emps,periods,records,incentives]=await Promise.all([dbSelect('employee_advances','id,employee_id,advance_number,amount,deducted_amount,advance_date,status',{order:{column:'advance_date',ascending:false},limit:200}),dbSelect('employees','id,full_name,employee_number,base_salary,wage_type',{eq:{status:'active'},order:{column:'full_name'}}),dbSelect('payroll_periods','id,period_number,period_start,period_end,status',{order:{column:'period_start',ascending:false},limit:30}),dbSelect('payroll_records','id,payroll_period_id,employee_id,basic_salary,bonuses,deductions,advances_deducted,net_salary,payment_status',{order:{column:'id',ascending:false},limit:300}),dbSelect('employee_incentives','id,employee_id,batch_number,title,amount,incentive_date,payroll_period_id',{order:{column:'incentive_date',ascending:false},limit:200})]);const names=Object.fromEntries(emps.map(e=>[e.id,e.full_name]));return `${head('المرتبات والسلفيات','كشف العامل يحسب الأساسي والحضور والحوافز ويخصم السلفيات عند اعتماد الراتب',btn('حافز جديد','incentive-modal'))}<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">كشف العاملين</h2><p class="panel-sub">ابحث بالاسم لمعرفة المستحق والخصومات والصافي</p></div><input class="search" data-search="payroll-table" placeholder="اكتب اسم العامل"></div>${table(['العامل','الأساسي','الحوافز','خصم السلفة','خصومات أخرى','الصافي','الحالة'],records.map(r=>`<tr><td><strong>${esc(names[r.employee_id]||'—')}</strong></td><td>${money(r.basic_salary)}</td><td>${money(r.bonuses)}</td><td>${money(r.advances_deducted)}</td><td>${money(r.deductions)}</td><td><strong>${money(r.net_salary)}</strong></td><td><span class="badge">${label(r.payment_status)}</span></td></tr>`))||empty('لم يُجهز كشف بعد','أنشئ فترة راتب ثم اضغط إعداد الكشف التلقائي.')}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">الحوافز</h2><p class="panel-sub">حافز فردي أو جماعي يظهر تلقائيًا في كشف الفترة</p></div></div>${table(['العامل','البيان','المبلغ','التاريخ','الفترة'],incentives.map(i=>`<tr><td><strong>${esc(names[i.employee_id]||'—')}</strong></td><td>${esc(i.title)}</td><td>${money(i.amount)}</td><td>${esc(i.incentive_date)}</td><td>${esc(periods.find(p=>p.id===i.payroll_period_id)?.period_number||'غير مربوط بعد')}</td></tr>`))}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">السلفيات</h2></div></div>${table(['العامل','رقم السلفية','المبلغ','المخصوم','المتبقي','التاريخ','الحالة'],adv.map(a=>`<tr><td><strong>${esc(names[a.employee_id]||'—')}</strong></td><td>${esc(a.advance_number)}</td><td>${money(a.amount)}</td><td>${money(a.deducted_amount)}</td><td>${money(Number(a.amount)-Number(a.deducted_amount))}</td><td>${dateText(a.advance_date)}</td><td>${label(a.status)}</td></tr>`))}</section><section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">فترات المرتبات</h2><p class="panel-sub">أنشئ الفترة ثم جهّز كشفها تلقائيًا من الحضور والحوافز والسلفيات</p></div><button class="btn btn-primary" data-action="payroll-period-modal">فترة راتب جديدة</button></div>${table(['الفترة','من','إلى','الحالة','الإجراء'],periods.map(p=>`<tr><td>${esc(p.period_number)}</td><td>${esc(p.period_start)}</td><td>${esc(p.period_end)}</td><td><span class="badge">${label(p.status)}</span></td><td><button class="btn btn-soft" data-action="prepare-payroll" data-id="${p.id}">إعداد الكشف</button> ${p.status==='draft'?approveBtn('approve_payroll_period',p.id):''}</td></tr>`))}</section>`}
async function guide(){return `${head('دليل التشغيل','أين تسجل كل عملية في المصنع؟',btn('العودة للوحة','dashboard','soft'))}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">خريطة النظام</h2><p class="panel-sub">اتبع المسار المناسب للعملية التي تريد تسجيلها</p></div></div><div class="section-grid"><a class="section-card" href="#/employees"><div class="section-icon">♙</div><h3>العامل ووظيفته</h3><p>الموظفون والوظائف: الاسم، الرقم، القسم، الوظيفة، الأجر والوردية.</p></a><a class="section-card" href="#/attendance"><div class="section-icon">◷</div><h3>الحضور والانصراف</h3><p>سجّل حضور العامل وانصرافه وتابع الورديات والساعات الناقصة.</p></a><a class="section-card" href="#/production"><div class="section-icon">⚙</div><h3>الإنتاج</h3><p>سجّل الكمية المخططة، المنتجة، المقبولة والتالف حسب الوردية.</p></a><a class="section-card" href="#/sales"><div class="section-icon">▣</div><h3>المبيعات</h3><p>أنشئ فاتورة بيع وحدد العميل والمخزن وطريقة الدفع.</p></a><a class="section-card" href="#/inventory"><div class="section-icon">▤</div><h3>المخزن</h3><p>سجّل الوارد والصادر، ولا تعدّل الرصيد يدويًا.</p></a><a class="section-card" href="#/expenses"><div class="section-icon">−</div><h3>المصروفات</h3><p>اكتب صُرف في شنو، المبلغ، الخزنة أو البنك، ثم اعتمد العملية.</p></a><a class="section-card" href="#/payroll"><div class="section-icon">₿</div><h3>المرتبات والسلفيات</h3><p>سجّل السلفية باسم العامل وتابع الخصم وفترات المرتبات.</p></a><a class="section-card" href="#/treasury"><div class="section-icon">▥</div><h3>الخزنة والبنوك</h3><p>راجع الرصيد والحركات المالية المرتبطة بالمبيعات والمصروفات.</p></a><a class="section-card" href="#/users"><div class="section-icon">♙</div><h3>المستخدمون والصلاحيات</h3><p>أنشئ مستخدمًا وحدد دوره؛ كل مستخدم يرى الأقسام المسموحة له فقط.</p></a></div></section><section class="panel table-panel"><h2 class="panel-title">ترتيب الإعداد أول مرة</h2><div class="metric-line"><span>1. إعداد المصنع</span><strong>إعدادات المصنع</strong></div><div class="metric-line"><span>2. المستخدمون والأدوار</span><strong>المستخدمون ← الأدوار والصلاحيات</strong></div><div class="metric-line"><span>3. تعريف العاملين</span><strong>الموظفون والوظائف</strong></div><div class="metric-line"><span>4. بدء التشغيل</span><strong>المخزن ← المبيعات ← الإنتاج ← المالية</strong></div></section>`}
async function reports(){return `${head('التقارير والطباعة','اختر التقرير والفترة، ثم اعرض أو اطبع النتيجة',btn('طباعة التقرير','print','outline'))}<section class="panel"><div class="form-grid"><label class="field">نوع التقرير<select id="report-type"><option value="sales">المبيعات</option><option value="expenses">المصروفات</option><option value="stock_movements">المخزن</option><option value="attendance_records">الحضور</option><option value="employee_advances">السلفيات</option><option value="activity_logs">سجل التدقيق</option></select></label><label class="field">من تاريخ<input id="report-from" type="date" value="${today()}"></label><label class="field">إلى تاريخ<input id="report-to" type="date" value="${today()}"></label><div class="field"><button class="btn btn-primary" data-action="report">عرض التقرير</button></div></div></section><section class="panel table-panel" id="report-result">${empty('اختر تقريرًا','اضغط عرض التقرير لإظهار النتائج.')}</section>`}
async function audit(){const rows=await dbSelect('activity_logs','id,action,entity_type,entity_id,severity,created_at',{order:{column:'created_at',ascending:false},limit:200});return `${head('سجل التدقيق','سجل غير قابل للتلاعب يوضح من أنشأ أو عدّل كل عملية') }<section class="panel table-panel">${table(['العملية','القسم','المعرّف','الخطورة','التاريخ'],rows.map(r=>`<tr><td>${esc(r.action)}</td><td>${esc(r.entity_type)}</td><td>${esc(r.entity_id||'—')}</td><td><span class="badge">${esc(r.severity)}</span></td><td>${dateText(r.created_at)}</td></tr>`))}</section>`}
async function settings(){const [depts,titles,shifts,wh,cats,exCats,regs,banks]=await Promise.all([dbSelect('departments','id,name',{order:{column:'name'}}),dbSelect('job_titles','id,name',{order:{column:'name'}}),dbSelect('shifts','id,name,start_time,end_time',{order:{column:'name'}}),dbSelect('warehouses','id,name,code',{order:{column:'name'}}),dbSelect('product_categories','id,name,product_type',{order:{column:'name'}}),dbSelect('expense_categories','id,name',{order:{column:'name'}}),dbSelect('cash_registers','id,name,opening_balance',{order:{column:'name'}}),dbSelect('banks','id,name',{order:{column:'name'}})]);return `${head('إعدادات المصنع','عرّف البيانات الأساسية مرة واحدة، ثم استخدمها في كل الشاشات',btn('إضافة بيانات أساسية','setup-modal'))}<section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h2 class="panel-title">حسابي</h2><p class="panel-sub">تعديل اسم المدير أو تغيير كلمة المرور دون الخروج من النظام</p></div></div><form id="account-form" class="form-grid"><label class="field">الاسم الظاهر<input name="full_name" value="${esc(profile?.full_name||'')}" required></label><label class="field">كلمة المرور الجديدة<input name="new_password" type="password" minlength="8" placeholder="اتركها فارغة إذا لا تريد تغييرها"></label><div class="full form-footer"><button class="btn btn-primary">حفظ بيانات الحساب</button></div></form></section><section class="section-grid">${[['الأقسام',depts.length,'employees'],['المسميات الوظيفية',titles.length,'employees'],['الورديات',shifts.length,'attendance'],['المخازن',wh.length,'inventory'],['تصنيفات المنتجات',cats.length,'products'],['تصنيفات المصروفات',exCats.length,'expenses'],['الخزن',regs.length,'treasury'],['البنوك',banks.length,'treasury']].map(x=>`<a class="section-card" href="#/${x[2]}"><div class="section-icon">◇</div><h3>${x[0]}</h3><p>${x[1]} سجل محفوظ</p></a>`).join('')}</section><section class="panel table-panel"><h2 class="panel-title">ترتيب الإعداد المقترح</h2><p class="panel-sub">ابدأ بالمخزن والخزنة وتصنيفات المنتجات، ثم المنتجات والموظفين والورديات. بعدها ابدأ تسجيل الوارد والمبيعات والحضور.</p></section><section class="panel danger-panel"><div class="panel-head"><div><h2 class="panel-title">منطقة المدير الحساسة</h2><p class="panel-sub">إعادة ضبط بيانات التشغيل تحذف السجلات المالية والتشغيلية والموظفين والمنتجات، مع إبقاء حسابات الدخول والأدوار محفوظة.</p></div><span class="badge warn">للمدير فقط</span></div><div class="danger-actions"><div><strong>إعادة ضبط بيانات المصنع</strong><p class="panel-sub">استخدمها عند بدء دورة تشغيل جديدة أو بعد أرشفة البيانات خارج النظام.</p></div><button class="btn btn-danger" data-action="factory-reset">إعادة ضبط البيانات</button></div></section>`}
async function view(r){if(!can(r))return `${head('غير مصرح','هذا القسم غير متاح لدورك الحالي')}<section class="panel">${empty('لا توجد صلاحية','يمكن للمدير تعديل دورك من الأدوار والصلاحيات.')}</section>`;try{return r==='dashboard'?dashboard():r==='users'?users():r==='roles'?roles():r==='employees'?employees():r==='attendance'?attendance():r==='products'?products():r==='inventory'?inventory():r==='production'?production():r==='sales'?sales():r==='expenses'?expenses():r==='treasury'?treasury():r==='payroll'?payroll():r==='reports'?reports():r==='audit'?audit():r==='guide'?guide():settings()}catch(e){return `${head('تعذر تحميل القسم','تحقق من الاتصال أو الصلاحية')}<section class="panel"><div class="error">${esc(friendlyError(e))}</div></section>`}}
function modal(id,title,body){return `<div class="modal-backdrop hidden" id="${id}"><div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" data-target="${id}">×</button></div>${body}</div></div>`}
function dynamicModal(id){let body='';if(id==='user-modal')body='<p class="panel-sub">إنشاء المستخدم يتم من لوحة إدارة آمنة ثم يُسند له الدور.</p><div class="form-grid"><label class="field">الاسم الكامل<input name="full_name"></label><label class="field">البريد الإلكتروني<input name="email" type="email"></label><label class="field">الدور<select name="role"><option>المدير</option><option>الحسابات</option><option>المبيعات</option><option>المخزن</option><option>الإنتاج</option></select></label></div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal" data-target="${id}">حفظ المستخدم</button></div>';else if(id==='employee-modal')body='<form id="employee-form" class="form-grid"><label class="field">اسم العامل *<input name="full_name" required></label><label class="field">رقم الهاتف<input name="phone"></label><label class="field">القسم<select name="department_id"></select></label><label class="field">الوظيفة<input name="job_title_text" placeholder="مثال: عامل إنتاج"></label><label class="field">نوع الأجر<select name="wage_type"><option value="monthly">شهري</option><option value="daily">يومي</option><option value="hourly">بالساعة</option></select></label><label class="field">الأجر الأساسي<input name="base_salary" type="number" min="0" value="0"></label><div class="full form-footer"><button class="btn btn-primary">حفظ الموظف</button></div></form>';else if(id==='setup-modal')body='<form id="setup-form" class="form-grid"><label class="field">ماذا تريد أن تضيف؟<select name="type"><option value="warehouse">مخزن</option><option value="department">قسم</option><option value="job_title">وظيفة</option><option value="product_category">تصنيف منتج</option><option value="expense_category">تصنيف مصروف</option><option value="shift">وردية</option><option value="cash_register">خزنة</option><option value="bank">بنك</option></select></label><label class="field">الاسم *<input name="name" required></label><label class="field">الكود<input name="code"></label><label class="field">الرصيد الافتتاحي<input name="opening_balance" type="number" value="0"></label><div class="full form-footer"><button class="btn btn-primary">حفظ البيانات</button></div></form>';else body='<p class="panel-sub">النموذج المختصر جاهز للتسجيل. أكمل البيانات المطلوبة ثم احفظ العملية كمسودة قبل الاعتماد.</p><div class="form-grid"><label class="field">رقم المستند<input></label><label class="field">البيان<input></label><label class="field">المبلغ / الكمية<input type="number"></label><label class="field">ملاحظات<textarea rows="2"></textarea></label></div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal" data-target="${id}">حفظ كمسودة</button></div>';return modal(id,routes[{employee:'employees',user:'users',setup:'settings',sale:'sales',stock:'inventory',expense:'expenses',cash:'treasury',production:'production',advance:'payroll',product:'products'}[id.replace('-modal','')]||'']?.[0]||'عملية جديدة',body)}
